function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 10) return 'grid needs 1 to 10 rows.';
  const cols = grid[0].length;
  if (cols < 1 || cols > 10) return 'grid needs 1 to 10 columns.';
  if (grid.some(row => row.length !== cols)) return 'Every row must have the same length.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 9))) return 'Each cell is an integer from 0 to 9.';
  return null;
}

