function satisfiesConditions(grid) {
  const rows = grid.length;
  const cols = grid[0].length;

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      const value = grid[i][j];
      if (i + 1 < rows && grid[i + 1][j] !== value) {
        return false;
      }
      if (j + 1 < cols && grid[i][j + 1] === value) {
        return false;
      }
    }
  }
  return true;
}

