function satisfiesConditions(grid) {
  // Every column must be constant, and then only the top row's neighbours need to differ.
  const top = grid[0];
  for (const row of grid) {
    if (row.some((v, j) => v !== top[j])) return false;
  }
  for (let j = 1; j < top.length; j++) {
    if (top[j] === top[j - 1]) return false;
  }
  return true;
}

