function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const rows = size === 'large' ? pick(8, 10) : pick(1, 4);
  const cols = size === 'large' ? pick(8, 10) : pick(1, 4);
  const top = size === 'large' ? 9 : 3;
  // Build a valid grid: a top row with no equal neighbours, copied down every column.
  const first = [];
  for (let j = 0; j < cols; j++) {
    let v = pick(0, top);
    while (j > 0 && v === first[j - 1]) v = pick(0, top);
    first.push(v);
  }
  const grid = Array.from({ length: rows }, () => first.slice());
  const mode = rand();
  if (mode < 0.35) return [grid];
  if (mode < 0.7) {
    // Break exactly one cell.
    const i = pick(0, rows - 1), j = pick(0, cols - 1);
    grid[i][j] = pick(0, top);
    return [grid];
  }
  if (mode < 0.85) {
    // Make one column match its left neighbour.
    if (cols > 1) {
      const j = pick(1, cols - 1);
      for (let i = 0; i < rows; i++) grid[i][j] = grid[i][j - 1];
    }
    return [grid];
  }
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => pick(0, top)))];
}
